from collections import deque

def is_enclosed_region_one_cell(region, grid, special_color):
    """
    Check if a single cell (that forms a region on its own) is surrounded by 8s on all 8 sides.
    Does not consider connectivity to other region cells.
    """
    h, w = len(grid), len(grid[0])

    if len(region) > 1:
        return False  # Multi-cell regions need special handling

    r, c = next(iter(region))

    # Check all 8 neighbors - all must be special_color
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] != special_color:
                    return False
    return True

def find_8connected_regions(grid, target_color):
    """Find 8-connected regions."""
    h, w = len(grid), len(grid[0])
    visited = set()
    regions = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == target_color and (r,c) not in visited:
                region = set()
                queue = deque([(r, c)])
                while queue:
                    curr_r, curr_c = queue.popleft()
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    region.add((curr_r, curr_c))

                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == target_color and (nr, nc) not in visited:
                                queue.append((nr, nc))
                regions.append(region)
    return regions

def find_special_color(grid):
    """Find the non-background color."""
    colors = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 6:
                colors.add(grid[r][c])
    return list(colors)[0]

def transform_old(grid):
    """Old rule: all 6-regions that are enclosed become 4."""
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    special_color = find_special_color(grid)

    regions = find_8connected_regions(grid, 6)

    for region in regions:
        # New rule: multi-cell regions must be larger than 0 and fully surrounded by special color
        # Single-cell closures need to be checked - all 8 neighbors must be special color
        h, w = len(grid), len(grid[0])
        if len(region) == 0:
